<script lang="ts">import { LoongArkProvider as Provider, LoongArkButton as Button, LoongArkInputRoot as InputRoot, LoongArkInputLabel as InputLabel, LoongArkInputControl as InputControl, LoongArkInputErrorText as InputErrorText, LoongArkDialogRoot as DialogRoot, LoongArkDialogTrigger as DialogTrigger, LoongArkDialogPortal as DialogPortal, LoongArkDialogOverlay as DialogOverlay, LoongArkDialogPositioner as DialogPositioner, LoongArkDialogContent as DialogContent, LoongArkDialogTitle as DialogTitle, LoongArkDialogDescription as DialogDescription, LoongArkDialogCloseTrigger as DialogCloseTrigger, LoongArkSwitchRoot as SwitchRoot, LoongArkSwitchControl as SwitchControl, LoongArkSwitchThumb as SwitchThumb, LoongArkSwitchLabel as SwitchLabel, LoongArkSwitchHiddenInput as SwitchHiddenInput, LoongArkSelectRoot as SelectRoot, LoongArkSelectLabel as SelectLabel, LoongArkSelectControl as SelectControl, LoongArkSelectTrigger as SelectTrigger, LoongArkSelectValueText as SelectValueText, LoongArkSelectPositioner as SelectPositioner, LoongArkSelectContent as SelectContent, LoongArkSelectItem as SelectItem, LoongArkSelectItemText as SelectItemText, LoongArkSelectHiddenSelect as SelectHiddenSelect, LoongArkPortal as Portal, LoongArkDataTable as DataTable, LoongArkChart as Chart, LoongArkSheetRoot as SheetRoot, LoongArkSheetTrigger as SheetTrigger, LoongArkSheetPortal as SheetPortal, LoongArkSheetOverlay as SheetOverlay, LoongArkSheetPositioner as SheetPositioner, LoongArkSheetContent as SheetContent, LoongArkSheetTitle as SheetTitle, LoongArkSheetDescription as SheetDescription, LoongArkSheetAction as SheetAction, createListCollection, LoongArkQuestionnaire as Questionnaire, type QuestionnaireValue } from '@loongark/svelte'; const plans=[{label:'Free',value:'free'},{label:'Pro',value:'pro'}];const collection=createListCollection({items:plans});const rows=[{id:'a',name:'Alpha',amount:20},{id:'b',name:'Beta',amount:10},{id:'c',name:'Gamma',amount:35}];const columns=[{key:'name',label:'Name'},{key:'amount',label:'Revenue'}];let email=''; let mode:'light'|'dark'='light';let freshNote:QuestionnaireValue|undefined;</script><Provider {mode}><section style="padding:24px;display:grid;gap:16px;min-height:100dvh;background:var(--lk-color-semantic-background);color:var(--lk-color-semantic-foreground)"><InputRoot state="invalid"><InputLabel>Email</InputLabel><InputControl data-testid="email" bind:value={email} /><InputErrorText>Enter a valid email</InputErrorText></InputRoot>
<Button data-testid="submit" disabled={!email}>Continue</Button>
<Button data-testid="mode" onclick={() => mode = mode === "light" ? "dark" : "light"}>Theme</Button>
<DialogRoot><DialogTrigger>Open dialog</DialogTrigger><DialogPortal><DialogOverlay /><DialogPositioner><DialogContent><DialogTitle>Review details</DialogTitle><DialogDescription>Theme follows this dialog.</DialogDescription><DialogCloseTrigger>Close</DialogCloseTrigger></DialogContent></DialogPositioner></DialogPortal></DialogRoot>
<form><SwitchRoot name="notifications"><SwitchControl><SwitchThumb/></SwitchControl><SwitchLabel>Notifications</SwitchLabel><SwitchHiddenInput/></SwitchRoot></form>
<SelectRoot collection={collection}><SelectLabel>Plan</SelectLabel><SelectControl><SelectTrigger data-testid="select"><SelectValueText placeholder="Choose a plan"/></SelectTrigger></SelectControl><Portal><SelectPositioner><SelectContent>{#each plans as item}<SelectItem {item}><SelectItemText>{item.label}</SelectItemText></SelectItem>{/each}</SelectContent></SelectPositioner></Portal><SelectHiddenSelect/></SelectRoot>
<DataTable data={rows} columns={columns} pageSize={2}/><Chart data={rows} series={[{key:'amount'}]} labelKey="name" title="Revenue"/>
<SheetRoot><SheetTrigger>Open sheet</SheetTrigger><SheetPortal><SheetOverlay/><SheetPositioner><SheetContent><SheetTitle>Edit profile</SheetTitle><SheetDescription>Update your settings.</SheetDescription><SheetAction>Save changes</SheetAction></SheetContent></SheetPositioner></SheetPortal></SheetRoot><Questionnaire label="Fresh feedback" questions={[{id:'note',label:'Fresh note',type:'text'}]} bind:value={freshNote}/><output aria-label="Bound fresh note">{freshNote?.note ?? ''}</output></section></Provider>